function stamp(g, x, y, txt, col, st) { if (st <= 0) return; g.save(); g.translate(x, y); g.rotate(-0.12); g.scale(1.4 - 0.4 * st, 1.4 - 0.4 * st); g.globalAlpha = st; g.font = '800 56px Inter'; const w = g.measureText(txt).width + 60; g.strokeStyle = col; g.lineWidth = 10; g.strokeRect(-w / 2, -55, w, 110); g.fillStyle = col; g.textAlign = 'center'; g.fillText(txt, 0, 20); g.restore(); }
function bubble(g, q, col) { if (q <= 0) return; g.fillStyle = rgba(col, q); g.beginPath(); g.roundRect(W / 2 - 150, H * 0.08, 300, 110, 30); g.fill(); g.fillStyle = '#0c0a10'; for (let j = 0; j < 3; j++) { g.beginPath(); g.arc(W / 2 - 70 + j * 70, H * 0.08 + 55, 14, 0, 6.283); g.fill(); } }
