  photo(g, BOMB, 0, H * 0.2, W, H * 0.42, 1.1 + 0.08 * k, 1); g.fillStyle = `rgba(255,120,40,${0.12 + 0.08 * Math.sin(t * 6)})`; g.fillRect(0, H * 0.2, W, H * 0.42);
